use vstd::prelude::*;

verus! {
    // longest_common_prefix returns the maximal common prefix of str1 and str2.
    // 
    // Ensures:
    //   • result.len() ≤ str1.len()  and  result.len() ≤ str2.len()
    //   • ∀ i < result.len(). result[i] == str1[i] == str2[i]
    //   • Maximality: either one input is exhausted, or the next characters differ
    fn longest_common_prefix(str1: &Vec<char>, str2: &Vec<char>) -> (result: Vec<char>)
        ensures
            result.len() <= str1.len(),
            result.len() <= str2.len(),
            forall|i: nat| i < result.len() ==> result[i] == str1[i] && result[i] == str2[i],
            result.len() == str1.len() || result.len() == str2.len() ||
                (result.len() < str1.len() && result.len() < str2.len() &&
                     str1[result.len()] != str2[result.len()]),
    {
        // Allocate empty result
        let mut result: Vec<char> = Vec::new();
        // Compute the smaller of the two lengths
        let min_len = if str1.len() < str2.len() { str1.len() } else { str2.len() };
        // idx = how many chars we have pushed so far
        let mut idx: usize = 0;

        // Consume characters while they match
        while idx < min_len && str1[idx] == str2[idx]
            invariant
                // idx is always ≤ the lengths
                idx <= min_len,
                idx <= str1.len(),
                idx <= str2.len(),
                // result.len() tracks idx
                result.len() == idx,
                // correctness of each pushed character
                forall|j: nat| j < result.len() ==> result[j] == str1[j] && result[j] == str2[j],
            decreases min_len - idx,
        {
            result.push(str1[idx]);
            idx += 1;
        }

        // At loop exit we know either
        //  • idx == min_len      (one string is exhausted), or
        //  • str1[idx] != str2[idx]  (first mismatch)
        assert(idx == str1.len() || idx == str2.len() || str1[idx] != str2[idx]);

        result
    }

    fn main() {
        // optional quick testing in `main`
        let a = Vec::from_slice(&['a','b','c','x']);
        let b = Vec::from_slice(&['a','b','c','y','z']);
        let p = longest_common_prefix(&a, &b);
        assert(p.len() == 3);
        assert(p[0] == 'a' && p[1] == 'b' && p[2] == 'c');
    }
}